/**
 * Builds a flat mapping of MIDI program numbers to SVG icons.
 * Populates MIDI_ICON_MAP based on defined ranges.
 */
function buildIconMap() {
    for (const r of MIDI_ICON_RANGES) {
        for (let i = r.min; i <= r.max; i++) {
            MIDI_ICON_MAP[i] = r.icon;
        }
    }
}



/**
 * Retrieves an SVG icon for a specific MIDI instrument or channel.
 * 
 * @param {number} programNumber - The MIDI program number (0-127).
 * @param {number} channel - The MIDI channel (0-15).
 * @returns {string} The SVG HTML string.
 */
function getMidiIcon(programNumber, channel) {
    if (channel === 9) return DRUM_ICON_SET.snare;
    if (typeof MIDI_ICON_MAP[programNumber] !== 'undefined') {
        return MIDI_ICON_MAP[programNumber];
    }
    return MIDI_ICONS.fallback;
}

/**
 * Helper function to modify the width and height attributes of an SVG string.
 * 
 * @param {string} svgString - The original SVG string.
 * @param {number} width - Target width.
 * @param {number} height - Target height.
 * @returns {string} The modified SVG string.
 */
function setIconSize(svgString, width, height) {
  return svgString
    .replace(/(<svg[^>]*?)\swidth="\d+"/, `$1 width="${width}"`)
    .replace(/(<svg[^>]*?)\sheight="\d+"/, `$1 height="${height}"`);
}

