/**
 * Returns a distinct CSS hex color for a given MIDI instrument ID.
 * 
 * @param {number} programId - MIDI program ID.
 * @returns {string} Hex color string.
 */
 function getInstrumentColor(programId) {
    const id = Math.max(0, Math.min(127, programId));
    return INSTRUMENT_COLORS[id % INSTRUMENT_COLORS.length];
}

/**
 * Returns a distinct CSS hex color for a given MIDI sound bank.
 * 
 * @param {number} bankId - Bank ID.
 * @returns {string} Hex color string.
 */
function getBankColor(bankId) {
    return BANK_COLORS[bankId % BANK_COLORS.length];
}

